package com.digitalbase.ticketing.service;import com.digitalbase.ticketing.dto.NotificationDto;import com.digitalbase.ticketing.exception.ResourceNotFoundException;import com.digitalbase.ticketing.model.ClientProduct; // 👈 ထပ်ဖြည့်ပါimport com.digitalbase.ticketing.model.Notification;import com.digitalbase.ticketing.model.User;import com.digitalbase.ticketing.repository.ClientProductRepository; // 👈 ထပ်ဖြည့်ပါimport com.digitalbase.ticketing.repository.NotificationRepository;import com.digitalbase.ticketing.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.data.domain.PageRequest;import org.springframework.data.domain.Pageable;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;import java.io.IOException;import java.util.List;import java.util.Map;import java.util.concurrent.ConcurrentHashMap;import java.util.concurrent.CopyOnWriteArrayList;import java.util.stream.Collectors;@Service@RequiredArgsConstructorpublic class NotificationSseServiceImpl implements NotificationSseService {    private final Map<String, List<SseEmitter>> userEmittersMap = new ConcurrentHashMap<>();    private final NotificationRepository notificationRepository;    private final UserRepository userRepository;    private final ClientProductRepository clientProductRepository; // 🎯 အသစ်ထပ်ဖြည့်ထားသည်    @Override    public SseEmitter subscribe(String email) {        SseEmitter emitter = new SseEmitter(3600000L); // 1 Hour        userEmittersMap.computeIfAbsent(email, k -> new CopyOnWriteArrayList<>()).add(emitter);        emitter.onCompletion(() -> removeEmitter(email, emitter));        emitter.onTimeout(() -> removeEmitter(email, emitter));        emitter.onError((e) -> removeEmitter(email, emitter));        return emitter;    }    private void removeEmitter(String email, SseEmitter emitter) {        List<SseEmitter> emitters = userEmittersMap.get(email);        if (emitters != null) {            emitters.remove(emitter);            if (emitters.isEmpty()) {                userEmittersMap.remove(email);            }        }    }    @Override    @Transactional    public void sendNotification(String userEmail, Notification notificationEntity) {        Notification savedNotification = notificationRepository.save(notificationEntity);        NotificationDto dto = mapToDto(savedNotification);        List<SseEmitter> emitters = userEmittersMap.get(userEmail);        if (emitters != null && !emitters.isEmpty()) {            for (SseEmitter emitter : emitters) {                try {                    emitter.send(SseEmitter.event().name("new-notification").data(dto));                } catch (IOException e) {                    emitter.complete();                    removeEmitter(userEmail, emitter);                }            }        }    }    // 🎯 [Update] Dashboard Dropdown ၏ Product ID အလိုက် Filter လုပ်ရန်    @Override    public Page<NotificationDto> getUserNotifications(String email, Long productId, int page, int size) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        Pageable pageable = PageRequest.of(page, size);        Page<Notification> notifications;        if (productId != null) {            // Product ရွေးထားလျှင် သက်ဆိုင်ရာ ClientProduct များ၏ Notification များကိုသာ ဆွဲထုတ်မည်            List<ClientProduct> cps = clientProductRepository.findAllByUserIdAndProductId(user.getId(), productId);            List<Long> cpIds = cps.stream().map(ClientProduct::getId).collect(Collectors.toList());            if (cpIds.isEmpty()) {                return Page.empty(); // ဝယ်ထားသော Product မရှိပါက            }            notifications = notificationRepository.findByUserIdAndClientProductIds(user.getId(), cpIds, pageable);        } else {            // Product မရွေးထားလျှင် အားလုံးကို ဆွဲထုတ်မည်            notifications = notificationRepository.findByUserIdOrderByCreatedAtDesc(user.getId(), pageable);        }        return notifications.map(this::mapToDto);    }    @Override    @Transactional    public void markAllAsRead(String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        List<Notification> unreadNotis = notificationRepository.findByUserIdAndIsReadFalse(user.getId());        for (Notification noti : unreadNotis) {            noti.setRead(true);        }        notificationRepository.saveAll(unreadNotis);    }    // 🎯 [အသစ်] Frontend မှ Ticket URL ကို နှိပ်လိုက်သောအခါ ဖတ်ပြီးကြောင်း မှတ်သားရန်    @Override    @Transactional    public void markNotificationAsRead(Long notificationId) {        Notification notification = notificationRepository.findById(notificationId)                .orElseThrow(() -> new ResourceNotFoundException("Notification not found"));        if (!notification.isRead()) {            notification.setRead(true);            notificationRepository.save(notification);        }    }    private NotificationDto mapToDto(Notification noti) {        return NotificationDto.builder()                .id(noti.getId())                .type(noti.getType().name())                .title(noti.getTitle())                .message(noti.getMessage())                .actionText(noti.getActionText())                .actionUrl(noti.getActionUrl())                .isRead(noti.isRead())                .createdAt(noti.getCreatedAt())                .build();    }}